import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SetSpawnPosition{SpawnType: packet.SpawnTypeWorld,
#   Position: protocol.BlockPos{1, 2, 3}, Dimension: 1,
#   SpawnPosition: protocol.BlockPos{4, 5, 6}}
WORLD = bytes.fromhex("0202040602080a0c")

# generated by gophertunnel b8bd735:
# &packet.SetSpawnPosition{SpawnType: packet.SpawnTypePlayer,
#   Position: protocol.BlockPos{-1, -64, 300}, Dimension: 2,
#   SpawnPosition: protocol.BlockPos{-2147483648, -2147483648, -2147483648}}
NEGATIVE = bytes.fromhex("00017fd80404ffffffff0fffffffff0fffffffff0f")

GOLDENS = [
    pytest.param(
        v2225.SetSpawnPositionPacket(
            spawn_pos_type=v2225.SpawnPositionType.WORLD_SPAWN,
            pos=v2225.BlockPos(x=1, y=2, z=3),
            dimension_type=1,
            spawn_block_pos=v2225.BlockPos(x=4, y=5, z=6),
        ),
        WORLD,
        id="world",
    ),
    pytest.param(
        v2225.SetSpawnPositionPacket(
            spawn_pos_type=v2225.SpawnPositionType.PLAYER_RESPAWN,
            pos=v2225.BlockPos(x=-1, y=-64, z=300),
            dimension_type=2,
            spawn_block_pos=v2225.BlockPos(x=-(2**31), y=-(2**31), z=-(2**31)),
        ),
        NEGATIVE,
        id="negative",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_set_spawn_position_is_packet_43(version):
    assert version.PACKETS[43] is version.SetSpawnPositionPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_spawn_position_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_spawn_position_decodes_from_its_golden(packet, golden):
    assert v2225.SetSpawnPositionPacket.from_bytes(golden) == packet
